"""Exercise the real Gradle runtime-config guard and restore generated bytes."""

import copy
import json
import os
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ANDROID = ROOT / "apps/client/android"
CONFIG = ANDROID / "app/src/main/assets/capacitor.config.json"
NAVIGATION_ERROR = "Remote WebView navigation is forbidden"


def main() -> None:
    if not os.environ.get("JAVA_HOME"):
        raise SystemExit("Set JAVA_HOME to the selected JDK 21 installation.")
    if not CONFIG.is_file():
        raise SystemExit("Run pnpm android:sync before testing the runtime configuration.")
    original = CONFIG.read_bytes()
    baseline = json.loads(original)
    cases = [
        ("bundled configuration", None, None),
        ("empty navigation list", [], None),
        ("wildcard navigation", ["*"], NAVIGATION_ERROR),
        ("remote host navigation", ["synthetic.invalid"], NAVIGATION_ERROR),
        ("malformed navigation setting", "*", NAVIGATION_ERROR),
    ]
    try:
        for label, navigation, expected_error in cases:
            config = copy.deepcopy(baseline)
            if navigation is not None:
                config.setdefault("server", {})["allowNavigation"] = navigation
            CONFIG.write_text(json.dumps(config) + "\n", encoding="utf-8")
            result = subprocess.run(
                ["./gradlew", "--no-daemon", ":app:validateBundledRuntimeConfig"],
                cwd=ANDROID,
                env=os.environ,
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                check=False,
            )
            if expected_error is None:
                passed = result.returncode == 0
            else:
                passed = result.returncode != 0 and expected_error in result.stdout
            if not passed:
                raise RuntimeError(f"Runtime-config check failed for {label}:\n{result.stdout}")
            print(f"PASS: {label}", flush=True)
    finally:
        CONFIG.write_bytes(original)
        if CONFIG.read_bytes() != original:
            raise RuntimeError("Generated runtime configuration was not restored byte-for-byte")
        print("Restored generated runtime configuration byte-for-byte.", flush=True)


if __name__ == "__main__":
    main()
